@startuml

class Doctor {
  + PractitionerNumber : int
  + FullName : string
  + Address : string
  + PhoneNumber : string
  + Signature : string
}

class Patient {
  + HealthNumber : string
  + FirstName : string
  + LastName : string
  + DateOfBirth : date
  + Address : string
  + PhoneNumber : string
}

class Requisition {
  + ValidFrom : date
  + RepetitionCount : int
  + RepetitionInterval : Interval
}

enum Interval {
  WEEKLY
  MONTHLY
  EVERY_HALF_YEAR
  YEARLY
}

class Test {
  + Duration : int
}

class TestGroup {
  + Name : string
}

class Lab {
  + Address : string
  + RegistrationNumber : string
  + StartTime : time
  + EndTime : time
  + ChangeCancellationFee : float
}

class Appointment {
  + ConfirmationNumber : string
  + Date : date
  + StartTime : time
  + EndTime : time
}

class TestResult {
  + Result : string
  + Report : string
}

Doctor "1" -- "*" Requisition : prescribes
Patient "1" -- "*" Requisition : receives
Requisition "1" *-- "1..*" Test : contains
Test "*" -- "1" TestGroup : belongs to
Doctor "0..1" -- "*" Requisition : is patient of
Patient "1" -- "*" Appointment : makes
Requisition "1" -- "0..1" Appointment : for
Lab "1" -- "*" Appointment : hosts
Lab "1" -- "*" Test : offers
Test "1" -- "0..*" TestResult : produces
Patient "1" -- "*" TestResult : views
Doctor "1" -- "*" TestResult : views

@enduml

